add_action( 'woocommerce_before_add_to_cart_quantity', 'perfectpixel_quantity_label' );

function perfectpixel_quantity_label() {
	global $product;
	if ( ! $product || $product->is_sold_individually() ) {
		return;
	}
	echo '<span class="perfectpixel-qty-label" style="display:inline-block;margin-right:.5em;vertical-align:middle;line-height:2.5">' . esc_html( '{{quantity_label_text}}' ) . '</span>';
}
